pub fn check_specialised(function: &str, on: &str) -> String {
    let mut tail: String = on.to_string();
    for (from, to) in [("::", "__"), (" -> ", "_to_"), (", ", "_"), ("[", "_"), ("]", "_"), ("(", "_of_"), (")", "_"), ("?", "_maybe"), (" ", "_")] { tail = tail.replace(from, to); }
    format!("{}__{}", function, tail)
}

